import{_ as s,c as t,o as e,ag as n}from"./chunks/framework.BwVZiZlf.js";const i="/assets/font-book-enable.CHHqNPoe.png",m=JSON.parse('{"title":"彻底解决！Chrome 打印/另存为 PDF 时中文字体不显示与乱码问题排查指南","description":"","frontmatter":{"date":"2026-08-05T00:00:00.000Z"},"headers":[],"relativePath":"blog/2026/08/05/fix-chrome-print-pdf-chinese-font-missing.md","filePath":"blog/2026/08/05/fix-chrome-print-pdf-chinese-font-missing.md","lastUpdated":1786675408000}'),o={name:"blog/2026/08/05/fix-chrome-print-pdf-chinese-font-missing.md"};function l(r,a,h,d,p,c){return e(),t("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1785888000000"},a[0]||(a[0]=[n('<h1 id="彻底解决-chrome-打印-另存为-pdf-时中文字体不显示与乱码问题排查指南" tabindex="-1">彻底解决！Chrome 打印/另存为 PDF 时中文字体不显示与乱码问题排查指南 <a class="header-anchor" href="#彻底解决-chrome-打印-另存为-pdf-时中文字体不显示与乱码问题排查指南" aria-label="Permalink to &quot;彻底解决！Chrome 打印/另存为 PDF 时中文字体不显示与乱码问题排查指南&quot;">​</a></h1><p>在日常工作和学习中，我们经常需要将网页保存为 PDF 文件方便归档或分享。然而，不少 Mac 及 Windows 用户在使用 Google Chrome 浏览器进行 <strong>“打印 -&gt; 另存为 PDF”</strong> 时，经常会遇到一个让人头疼的问题：</p><blockquote><p><strong>导出的 PDF 文件中，原本正常的中文内容变成了空白、方框（□）、问号或者乱码！</strong> 甚至有时在 Chrome 打印预览窗口中看着一切正常，但保存出来用 macOS 自带的“预览”应用（Preview.app）打开时，文字却全不见了。</p></blockquote><p>这个问题在 Apple 官方支持社区（<a href="https://discussionschinese.apple.com/thread/255765808?sortBy=rank" target="_blank" rel="noreferrer">Apple Discussions Community</a>）以及各类开发者论坛上引发了大量讨论。</p><p>本文将深入分析该问题背后的技术成因，并提供 <strong>5 种从根源到快速应急的解决方案</strong>，帮你彻底摆脱 Chrome PDF 打印乱码的困扰。</p><hr><h2 id="💡-一、为什么网页显示正常-导出-pdf-却缺失中文字体" tabindex="-1">💡 一、为什么网页显示正常，导出 PDF 却缺失中文字体？ <a class="header-anchor" href="#💡-一、为什么网页显示正常-导出-pdf-却缺失中文字体" aria-label="Permalink to &quot;💡 一、为什么网页显示正常，导出 PDF 却缺失中文字体？&quot;">​</a></h2><p>要解决问题，首先需要理解为什么网页屏幕显示与 PDF 导出结果不一致：</p><ol><li><strong>Chromium PDF 引擎的字体嵌入机制（Font Subsetting）</strong>：<br> Chrome 在生成 PDF 时，使用的是内置的 Skia / PDFium 渲染引擎。它不会直接对网页进行截屏，而是需要提取字体文件并尝试将用到的字符嵌入（Embed）到 PDF 流中。如果系统缺失对应字体的物理文件或字形映射失败，引擎就会回退（Fallback）到空字符或缺字方块。</li><li><strong>macOS 字体册（Font Book）的动态激活与云端下载机制</strong>：<br> 在 macOS 系统中，部分中文字体（如 <code>PingFang SC</code> 苹方、<code>Songti SC</code> 宋体、<code>Kaiti SC</code> 楷体等）的部分字重或字体族默认可能处于“未下载”或“未激活”状态。屏幕渲染时系统可以通过 CoreText 自动做替代渲染，但 Chrome 的 PDFium 引擎无法直接读取未激活的字体文件。</li><li><strong>网页 CSS 的 <code>font-family</code> 声明不规范</strong>：<br> 部分网站使用了自定义 WebFont 或仅仅指定了非标准的中文字体名称，没有在 CSS 中配置回退字体链（Fallback chain），导致 Chrome 打印引擎无法映射到本地的标准中文字库。</li><li><strong>macOS “预览”应用与 Adobe Reader 的编码解析差异</strong>：<br> Chrome 生成的部分 CID 编码 PDF 在没有完整嵌入字形时，macOS 自带的“预览”应用解析极易出现字形丢失，而在 Chrome 内部或 Adobe Acrobat 打开可能表现不同。</li></ol><hr><h2 id="🛠️-二、5-大解决方案-按推荐程度排序" tabindex="-1">🛠️ 二、5 大解决方案（按推荐程度排序） <a class="header-anchor" href="#🛠️-二、5-大解决方案-按推荐程度排序" aria-label="Permalink to &quot;🛠️ 二、5 大解决方案（按推荐程度排序）&quot;">​</a></h2><h3 id="方案-1-补全并激活-macos-字体册中的中文字体-最根源修复" tabindex="-1">方案 1：补全并激活 macOS 字体册中的中文字体（最根源修复） <a class="header-anchor" href="#方案-1-补全并激活-macos-字体册中的中文字体-最根源修复" aria-label="Permalink to &quot;方案 1：补全并激活 macOS 字体册中的中文字体（最根源修复）&quot;">​</a></h3><p>大多数 Mac 用户出现此问题的根本原因，都是因为 macOS 系统的中文基础字体处于<strong>未激活/未完全下载</strong>状态。</p><h4 id="操作步骤" tabindex="-1">操作步骤： <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤：&quot;">​</a></h4><ol><li>按下 <code>Cmd + 空格</code> 键打开 Spotlight 搜索，输入并打开 <strong>字体册</strong>（Font Book）。</li><li>在左侧栏选择 <strong>所有字体</strong>（All Fonts），并在右上角搜索框中依次搜索常用的中文字体： <ul><li><code>PingFang SC</code> / <code>苹方-简</code></li><li><code>Songti SC</code> / <code>宋体-简</code></li><li><code>Heiti SC</code> / <code>黑体-简</code></li><li><code>Kaiti SC</code> / <code>楷体-简</code></li></ul></li><li>检查搜索结果：如果字体名称显示为灰色，或者旁边带有“未下载/禁用”的提示，说明该字体未就绪。</li><li><strong>右键点击该字体</strong>，选择 <strong>下载</strong>（Download）或 <strong>激活</strong>（Enable）。</li><li><strong>非常重要的一步</strong>：修改完成后，按下 <code>Cmd + Q</code> 彻底退出 Chrome 浏览器并重新打开。</li></ol><p><img src="'+i+`" alt=""></p><blockquote><p><strong>效果</strong>：激活系统基础中文字体后，Chrome 即可正常提取本地字形嵌入 PDF，彻底解决空白和方框问题。</p></blockquote><hr><h3 id="方案-2-使用-macos-系统打印对话框替代-chrome-原生打印-一秒绕过-bug" tabindex="-1">方案 2：使用 macOS 系统打印对话框替代 Chrome 原生打印（一秒绕过 Bug） <a class="header-anchor" href="#方案-2-使用-macos-系统打印对话框替代-chrome-原生打印-一秒绕过-bug" aria-label="Permalink to &quot;方案 2：使用 macOS 系统打印对话框替代 Chrome 原生打印（一秒绕过 Bug）&quot;">​</a></h3><p>如果你当前急需导出文件，没有时间排查字体，这是最快、最有效的应急方案。它可以跳过 Chrome 内置的 PDF 引擎，直接调用 macOS 原生系统级 CoreText 打印引擎。</p><h4 id="操作步骤-1" tabindex="-1">操作步骤： <a class="header-anchor" href="#操作步骤-1" aria-label="Permalink to &quot;操作步骤：&quot;">​</a></h4><ol><li>在 Chrome 中按下 <code>Cmd + P</code> 打开打印界面。</li><li>滚动到左侧面板底部，展开 <strong>更多设置</strong>（More settings）。</li><li>点击 <strong>使用系统对话框打印...</strong>（Print using system dialog...），或者直接按下快捷键：<br> 👉 <code>Cmd + Option + P</code></li><li>在弹出的 macOS 系统原生打印对话框中，点击左下角的 <strong>PDF</strong> 下拉菜单。</li><li>选择 <strong>存储为 PDF</strong>（Save as PDF）。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-------------------------------------------------------------+</span></span>
<span class="line"><span>| Chrome 打印面板 (Cmd+P)                                      |</span></span>
<span class="line"><span>|  └── 展开 &quot;更多设置&quot; (More settings)                         |</span></span>
<span class="line"><span>|       └── 点击 &quot;使用系统对话框打印&quot; (Cmd + Option + P)         |</span></span>
<span class="line"><span>+-------------------------------------------------------------+</span></span>
<span class="line"><span>                               │</span></span>
<span class="line"><span>                               ▼</span></span>
<span class="line"><span>+-------------------------------------------------------------+</span></span>
<span class="line"><span>| macOS 系统原生打印对话框                                      |</span></span>
<span class="line"><span>|  └── 左下角按钮: [ PDF ▾ ]                                  |</span></span>
<span class="line"><span>|       └── 选择: &quot;存储为 PDF&quot; (Save as PDF)                   |</span></span>
<span class="line"><span>+-------------------------------------------------------------+</span></span></code></pre></div><blockquote><p><strong>原理</strong>：macOS 原生系统打印对话框使用的是苹果官方的 CoreText / Quartz PDF 引擎，对 macOS 字体库的兼容性接近 100%，生成的 PDF 绝不会出现中文缺失。</p></blockquote><hr><h3 id="方案-3-修改-chrome-默认-自定义字体-配置" tabindex="-1">方案 3：修改 Chrome 默认“自定义字体”配置 <a class="header-anchor" href="#方案-3-修改-chrome-默认-自定义字体-配置" aria-label="Permalink to &quot;方案 3：修改 Chrome 默认“自定义字体”配置&quot;">​</a></h3><p>如果 Chrome 浏览器的默认中文字体映射紊乱，也可以通过手动修改 Chrome 的字体设置来解决。</p><h4 id="操作步骤-2" tabindex="-1">操作步骤： <a class="header-anchor" href="#操作步骤-2" aria-label="Permalink to &quot;操作步骤：&quot;">​</a></h4><ol><li>在 Chrome 地址栏输入并打开：<code>chrome://settings/fonts</code></li><li>检查以下各项字体设置： <ul><li><strong>标准字体 (Standard font)</strong>：设置为 <code>PingFang SC</code>（苹方-简）或 <code>Microsoft YaHei</code>（微软雅黑）。</li><li><strong>无衬线字体 (Sans-serif font)</strong>：设置为 <code>PingFang SC</code>。</li><li><strong>衬线字体 (Serif font)</strong>：设置为 <code>Songti SC</code>（宋体-简）。</li></ul></li><li>调整完毕后，刷新目标网页，重新尝试 <code>Cmd + P</code> 另存为 PDF。</li></ol><hr><h3 id="方案-4-开发者-高级用户技巧-开发者工具注入-css-字体覆盖" tabindex="-1">方案 4：开发者/高级用户技巧：开发者工具注入 CSS 字体覆盖 <a class="header-anchor" href="#方案-4-开发者-高级用户技巧-开发者工具注入-css-字体覆盖" aria-label="Permalink to &quot;方案 4：开发者/高级用户技巧：开发者工具注入 CSS 字体覆盖&quot;">​</a></h3><p>如果你遇到的问题是因为特定网页的 CSS 样式指定了异常字体导致打印失败，可以通过 Chrome 开发者工具临时注入通用字体。</p><h4 id="操作步骤-3" tabindex="-1">操作步骤： <a class="header-anchor" href="#操作步骤-3" aria-label="Permalink to &quot;操作步骤：&quot;">​</a></h4><ol><li>在网页上按下 <code>F12</code> 或 <code>Cmd + Option + I</code> 打开 <strong>开发者工具</strong>（DevTools）。</li><li>切换到 <strong>Console</strong>（控制台）标签页。</li><li>复制并粘贴以下代码并回车执行：</li></ol><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> style</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> document.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">createElement</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;style&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">style.innerHTML </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> \`</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  @media print {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    * {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      font-family: -apple-system, BlinkMacSystemFont, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, sans-serif !important;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    }</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">document.head.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">appendChild</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(style);</span></span></code></pre></div><ol start="4"><li>再次按下 <code>Cmd + P</code> 进行 PDF 导出，网页在打印时会被强制使用本地已安装的标准中文字体。</li></ol><hr><h3 id="方案-5-借助-safari-导出或-阅读模式-插件" tabindex="-1">方案 5：借助 Safari 导出或“阅读模式”插件 <a class="header-anchor" href="#方案-5-借助-safari-导出或-阅读模式-插件" aria-label="Permalink to &quot;方案 5：借助 Safari 导出或“阅读模式”插件&quot;">​</a></h3><p>如果上述方法仍不满意，还可以尝试切换渲染管道：</p><ol><li><strong>使用 Safari 导出</strong>：复制网页 URL，在 macOS Safari 浏览器中打开，点击菜单栏 <strong>文件 -&gt; 导出为 PDF...</strong>。Safari 与 macOS 系统集成度最高，处理中文 PDF 从不踩坑。</li><li><strong>使用“阅读模式”/ PrintFriendly 插件</strong>：安装 PrintFriendly 等浏览器扩展，先把网页转换为纯净排版后再导出 PDF，可以有效过滤复杂的网页 WebFont 干扰。</li></ol><hr><h2 id="📝-三、总结与避坑建议" tabindex="-1">📝 三、总结与避坑建议 <a class="header-anchor" href="#📝-三、总结与避坑建议" aria-label="Permalink to &quot;📝 三、总结与避坑建议&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">场景</th><th style="text-align:left;">推荐解决方案</th><th style="text-align:left;">优点</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>彻底根治</strong></td><td style="text-align:left;"><strong>方案 1：在 macOS 字体册中激活/补全中文字体</strong></td><td style="text-align:left;">解决所有 Chromium 架构软件（Chrome, Edge, VS Code）的打印字体问题</td></tr><tr><td style="text-align:left;"><strong>最快应急</strong></td><td style="text-align:left;"><strong>方案 2：使用快捷键 <code>Cmd + Option + P</code> 调用系统 PDF 打印</strong></td><td style="text-align:left;">无需配置，1 秒绕过 Chrome PDF 引擎 Bug</td></tr><tr><td style="text-align:left;"><strong>网页开发者排查</strong></td><td style="text-align:left;"><strong>方案 4：注入 CSS 强制标准中文字体回退</strong></td><td style="text-align:left;">适合排查自定义 WebFont 导致的缺字问题</td></tr></tbody></table><p><strong>终极避坑建议</strong>：在 Mac 上遇到 Chrome 导出 PDF 缺字时，<strong>不要盲目重装浏览器或清理缓存</strong>。90% 的情况下，直接按下 <code>Cmd + Option + P</code> 调用系统打印对话框，或者去“字体册”补全下载 <code>PingFang SC</code> 就能完美解决！</p><hr><blockquote><p><strong>参考链接</strong>：</p><ul><li><a href="https://discussionschinese.apple.com/thread/255765808?sortBy=rank" target="_blank" rel="noreferrer">Apple 官方支持社区讨论：Chrome 另存为 PDF 中文字体丢失问题</a></li><li><a href="https://bugs.chromium.org/p/chromium/issues/list" target="_blank" rel="noreferrer">Chromium Issue Tracker: Skia PDF font embedding fallback</a></li></ul></blockquote>`,46)]))}const k=s(o,[["render",l]]);export{m as __pageData,k as default};
